import { CommonModule } from "@angular/common";
import { Component, computed, input, linkedSignal, output } from "@angular/core";

@Component({
  selector: "ap-toggle-switch",
  imports: [CommonModule],
  templateUrl: "./ap-toggle-switch.component.html",
  styleUrl: "./ap-toggle-switch.component.css",
  host: {
    "[class.flex]": "labelNotContentMode()",
    "[class.items-center]": "labelNotContentMode()",
    "[class.gap-2]": "hasLabel()",
    "[class.inline-flex]": "isContentMode()",
    "[class.justify-between]": "isContainerMode()",
    "[class.block]": "isContainerMode()",
    "[class.w-full]": "isContainerMode()",
  },
})
export class ApToggleSwitchComponent {
  /** 切換開關的標籤文字，預設為 null，不顯示標籤 */
  readonly label = input<string | null>(null);
  /** 切換開關的大小，預設為 medium */
  readonly size = input<"small" | "medium" | "large">("medium");
  /** 主色調，預設為橘色 */
  readonly accentColor = input<"orange" | "yellow" | "purple" | "slate" | undefined>(undefined);
  /** 是否停用切換開關，預設為 false，true 時仍會顯示，只是無法用點擊切換，可以用 input checked 切換 */
  readonly disabled = input(false);
  /** 切換是依照內容調整符合大小或是依照父容器調整大小 */
  readonly fitMode = input<"content" | "container">("content");
  readonly checked = input(true);
  readonly checkedChange = output<boolean>();
  /** 內部狀態：checked input 變動時會重設，點擊時可本地切換 */
  readonly isChecked = linkedSignal(() => this.checked());

  // ======= Host / Template 專用條件 =======
  readonly hasLabel = computed(() => this.label() !== null);
  readonly isContentMode = computed(() => this.fitMode() === "content");
  readonly isContainerMode = computed(() => this.fitMode() === "container");
  readonly labelNotContentMode = computed(() => this.hasLabel() && !this.isContentMode());

  readonly thumbTranslateX = computed(() => {
    if (!this.isChecked()) {
      return "0.25rem";
    }
    switch (this.size()) {
      case "small":
        return "2rem";
      case "large":
        return "2.75rem";
      default:
        return "2.25rem";
    }
  });

  toggle(): void {
    this.isChecked.update((checked) => !checked);
    this.checkedChange.emit(this.isChecked());
  }
}
